import{_ as t,o as e,c as a,a2 as o}from"./chunks/framework.D_M-uDGM.js";const p=JSON.parse('{"title":"Fluffy theme: asset requests","description":"","frontmatter":{},"headers":[],"relativePath":"guide/fluffy-assets.md","filePath":"guide/fluffy-assets.md"}'),c={name:"guide/fluffy-assets.md"};function h(s,n,i,r,l,g){return e(),a("div",null,[...n[0]||(n[0]=[o(`<h1 id="fluffy-theme-asset-requests" tabindex="-1">Fluffy theme: asset requests <a class="header-anchor" href="#fluffy-theme-asset-requests" aria-label="Permalink to &quot;Fluffy theme: asset requests&quot;">​</a></h1><p>Bản game phụ mới, <strong>Fluffy</strong> (sẽ ở <code>/fluffy/</code>, nút <strong>Play Fluffy</strong> ở trang chủ). Cùng level và luật chơi như bản thường; khác ở nhân vật và nền:</p><ul><li>Mỗi hạt là <strong>một cục bông lông có mặt</strong>, phong cách 3D cartoon, vui nhộn, dễ thương.</li><li>Nền là <strong>pattern các khuôn mặt cục lông</strong>, xếp chéo và <strong>cuộn chậm theo đường chéo</strong> (từ trên trái xuống dưới phải).</li><li>Pinch zoom thì <strong>nền zoom theo board</strong>, nên ảnh nền phải đủ nét ở mức zoom lớn nhất (3 lần).</li></ul><h2 id="hanh-vi-code-lam-anh-chi-can-đung-quy-cach" tabindex="-1">Hành vi (code làm, ảnh chỉ cần đúng quy cách) <a class="header-anchor" href="#hanh-vi-code-lam-anh-chi-can-đung-quy-cach" aria-label="Permalink to &quot;Hành vi (code làm, ảnh chỉ cần đúng quy cách)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lúc</th><th>Mặt</th><th>Chuyển động / hiệu ứng</th></tr></thead><tbody><tr><td>Đứng yên (idle)</td><td>Nhắm mắt ngủ</td><td><strong>Thở</strong>: phồng xẹp nhè nhẹ, nhấp nhô lên xuống, mỗi cục lệch nhịp nhau</td></tr><tr><td>Đang chạy trên dây</td><td>Mắt mở to, ngạc nhiên</td><td>Kéo dãn theo hướng chạy, lông hơi rung</td></tr><tr><td>Va chạm với bóng khác</td><td>Mắt <code>&gt; &lt;</code></td><td>Bẹp lại rồi nảy; <strong>lông bay ra</strong> (vài túm lông màu của cục đó) ở cả hai cục</td></tr><tr><td>Đứng yên, cặp đã từng va chạm</td><td>Thức, mở mắt (thay cho sọc trắng; chỉ bật khi đã có ảnh, chưa có thì vẫn ngủ và có sọc)</td><td>Vẫn thở như lúc ngủ</td></tr><tr><td>Về tới bóng cùng cặp</td><td>Mắt <code>^ ^</code> vui vẻ</td><td>Ôm nhau một nhịp rồi biến mất, <strong>bay ra các trái tim nhỏ</strong></td></tr></tbody></table><p>Mặt được đổi bằng cách chồng <strong>ảnh mặt</strong> lên <strong>ảnh thân</strong>, nên thân và mặt là các file riêng. Thân được tô màu bằng code cho đủ 28 màu của bảng màu, giống bóng orb của bản Magic. Code tự làm cả co giãn, nhịp thở, mặt đổi theo trạng thái, hạt bay và nền cuộn.</p><h2 id="quy-cach-chung" tabindex="-1">Quy cách chung <a class="header-anchor" href="#quy-cach-chung" aria-label="Permalink to &quot;Quy cách chung&quot;">​</a></h2><ul><li><strong>Định dạng:</strong> PNG, sRGB. Cỡ ghi ở từng ảnh; ra cỡ to hơn cùng tỉ lệ cũng được, mình sẽ thu nhỏ.</li><li><strong>Nền trong suốt:</strong> thân, mặt và hạt cần nền trong suốt thật. Nếu công cụ có tùy chọn <em>transparent background</em> thì dùng. Nếu không, xin <strong>nền trắng tuyệt đối #FFFFFF</strong> cho thân (lông trắng tách khỏi nền trắng khó, nên tránh dùng nền xanh vì lông sẽ ám màu xanh ở mép) và <strong>nền xanh lá thuần #00FF00</strong> cho mặt và hạt.</li><li><strong>Đọc được khi nhỏ:</strong> hạt trên màn hình chỉ cao khoảng 25–40 px (khi zoom tối đa khoảng 100 px). Mắt phải <strong>to, đơn giản, đậm nét</strong>: không lông mi, không chi tiết nhỏ.</li><li><strong>Thân tròn:</strong> viền ngoài của cục lông phải gần tròn (va chạm tính theo hình tròn). Lông xù ra ngoài vòng tròn chính không quá 10% bán kính.</li><li><strong>Cùng phong cách:</strong> dán đoạn <em>Style</em> vào đầu các prompt thân và mặt.</li><li><strong>Không có chữ, logo, watermark.</strong></li></ul><h2 id="prompts" tabindex="-1">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to &quot;Prompts&quot;">​</a></h2><h3 id="style-dan-vao-đau-prompt-1–5" tabindex="-1">Style (dán vào đầu prompt 1–5) <a class="header-anchor" href="#style-dan-vao-đau-prompt-1–5" aria-label="Permalink to &quot;Style (dán vào đầu prompt 1–5)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Style: cute 3D cartoon render, soft and squishy, plush toy look, smooth soft lighting from the top left, gentle ambient occlusion, funny and adorable, clean simple shapes that read at a very small size, high resolution.</span></span></code></pre></div><h3 id="_1-ball-png-bat-buoc-than-cuc-long" tabindex="-1">1. <code>ball.png</code> (bắt buộc): thân cục lông <a class="header-anchor" href="#_1-ball-png-bat-buoc-than-cuc-long" aria-label="Permalink to &quot;1. \`ball.png\` (bắt buộc): thân cục lông&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Style]</span></span>
<span class="line"><span>A single round fluffy pom-pom creature body, perfectly round silhouette, seen straight-on, made of soft dense short fur with a few small tufts sticking out evenly all around the edge (no long strands), no face, no eyes, no mouth, no arms, no legs.</span></span>
<span class="line"><span>The fur is neutral light grey (no colour tint at all, it will be recoloured in code), slightly lighter at the top left where the light hits and slightly darker at the bottom right, with a soft white highlight on the top left.</span></span>
<span class="line"><span>Centred, the round body filling about 80 percent of the image width, the fur tufts staying inside the image.</span></span>
<span class="line"><span>Isolated on a transparent background (if transparency is not available: a pure flat white background #FFFFFF), no shadow on the ground, no reflections.</span></span>
<span class="line"><span>Square, 512 x 512 pixels.</span></span>
<span class="line"><span>Negative: face, eyes, mouth, text, watermark, colour tint, long hair, strands crossing the edge of the image, ground shadow, multiple objects.</span></span></code></pre></div><h3 id="_2–5-bon-khuon-mat-bat-buoc-face-sleep-png-face-surprised-png-face-ouch-png-face-happy-png" tabindex="-1">2–5. Bốn khuôn mặt (bắt buộc): <code>face-sleep.png</code>, <code>face-surprised.png</code>, <code>face-ouch.png</code>, <code>face-happy.png</code> <a class="header-anchor" href="#_2–5-bon-khuon-mat-bat-buoc-face-sleep-png-face-surprised-png-face-ouch-png-face-happy-png" aria-label="Permalink to &quot;2–5. Bốn khuôn mặt (bắt buộc): \`face-sleep.png\`, \`face-surprised.png\`, \`face-ouch.png\`, \`face-happy.png\`&quot;">​</a></h3><p>Mỗi mặt là <strong>một ảnh riêng, chỉ có mắt, miệng và má hồng</strong>, không có thân. Bốn ảnh phải <strong>cùng cỡ, cùng vị trí và cùng tỉ lệ</strong>: mặt nằm giữa ảnh, hơi lệch lên trên, rộng khoảng 55% chiều rộng ảnh, để đặt chồng đúng lên <code>ball.png</code>. Mẹo: tạo một mặt trước, rồi dùng ảnh đó làm tham chiếu (image reference) cho ba mặt còn lại.</p><p>Đoạn chung cho cả bốn prompt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Style]</span></span>
<span class="line"><span>Only a cartoon face to be placed on top of a round fluffy ball: two big simple eyes, a tiny mouth and two soft pink blush ovals on the cheeks. No body, no fur, no outline of a head.</span></span>
<span class="line"><span>The face is centred horizontally and slightly above the centre of the image, about 55 percent of the image width.</span></span>
<span class="line"><span>Eyes and mouth are glossy dark brown-black with a small white highlight, bold and simple so they read when the whole ball is only 30 pixels tall.</span></span>
<span class="line"><span>Isolated on a transparent background (if transparency is not available: a pure flat chroma-key green background #00FF00, with nothing green in the face).</span></span>
<span class="line"><span>Square, 512 x 512 pixels.</span></span>
<span class="line"><span>Negative: body, fur, head outline, eyebrows, eyelashes, nose, teeth, text, watermark, extra details.</span></span></code></pre></div><p>Rồi thêm một dòng tùy theo mặt:</p><table tabindex="0"><thead><tr><th>File</th><th>Thêm vào prompt</th></tr></thead><tbody><tr><td><code>face-sleep.png</code></td><td><code>Expression: peacefully asleep, both eyes closed as gentle downward curved lines, a small relaxed smile, cheeks a little pinker.</code></td></tr><tr><td><code>face-surprised.png</code></td><td><code>Expression: surprised and excited, both eyes wide open and round with big white highlights, a small open round &quot;o&quot; mouth.</code></td></tr><tr><td><code>face-ouch.png</code></td><td><code>Expression: bumped and squished, both eyes shut tight drawn as &quot;&gt;&quot; and &quot;&lt;&quot; shapes, a small wavy worried mouth.</code></td></tr><tr><td><code>face-happy.png</code></td><td><code>Expression: overjoyed, both eyes drawn as happy upside-down U arcs &quot;^ ^&quot;, a wide open happy smile, cheeks extra pink.</code></td></tr></tbody></table><h3 id="_6-fur-png-nen-co-tum-long-bay-ra-khi-va-cham" tabindex="-1">6. <code>fur.png</code> (nên có): túm lông bay ra khi va chạm <a class="header-anchor" href="#_6-fur-png-nen-co-tum-long-bay-ra-khi-va-cham" aria-label="Permalink to &quot;6. \`fur.png\` (nên có): túm lông bay ra khi va chạm&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single small soft tuft of fluffy fur, slightly curved, wispy at the ends, neutral white to light grey (no colour tint, it will be recoloured in code), soft 3D cartoon render.</span></span>
<span class="line"><span>Isolated on a transparent background (if transparency is not available: a pure flat chroma-key green background #00FF00).</span></span>
<span class="line"><span>Centred, filling about 70 percent of the image, square, 128 x 128 pixels.</span></span>
<span class="line"><span>Negative: text, watermark, colour tint, multiple tufts, shadow.</span></span></code></pre></div><h3 id="_7-heart-png-nen-co-trai-tim-nho-khi-ve-voi-cap" tabindex="-1">7. <code>heart.png</code> (nên có): trái tim nhỏ khi về với cặp <a class="header-anchor" href="#_7-heart-png-nen-co-trai-tim-nho-khi-ve-voi-cap" aria-label="Permalink to &quot;7. \`heart.png\` (nên có): trái tim nhỏ khi về với cặp&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single small cute puffy 3D cartoon heart, soft and glossy, bright pink-red with a white highlight at the top left, a thin slightly darker outline.</span></span>
<span class="line"><span>Isolated on a transparent background (if transparency is not available: a pure flat chroma-key green background #00FF00, with no green in the heart).</span></span>
<span class="line"><span>Centred, filling about 75 percent of the image, square, 128 x 128 pixels.</span></span>
<span class="line"><span>Negative: text, watermark, face, multiple hearts, shadow, sparkles.</span></span></code></pre></div><h3 id="_8-pattern-light-png-va-pattern-dark-png-bat-buoc-nen-pattern-cuon-cheo" tabindex="-1">8. <code>pattern-light.png</code> và <code>pattern-dark.png</code> (bắt buộc): nền pattern cuộn chéo <a class="header-anchor" href="#_8-pattern-light-png-va-pattern-dark-png-bat-buoc-nen-pattern-cuon-cheo" aria-label="Permalink to &quot;8. \`pattern-light.png\` và \`pattern-dark.png\` (bắt buộc): nền pattern cuộn chéo&quot;">​</a></h3><p>Nền được lặp lại (tile) và cuộn liên tục, nên ảnh <strong>phải nối liền mép</strong> (mép trái khớp mép phải, mép trên khớp mép dưới). Midjourney: thêm <code>--tile</code>. Công cụ khác: chọn chế độ <em>seamless / tileable pattern</em>. Hai ảnh: một cho theme sáng (nền kem <code>#F2EEE6</code>), một cho theme tối (nền xanh đậm <code>#1F2335</code>).</p><ul><li><strong>Cỡ: 2048 × 2048.</strong> Mỗi ô lặp phủ khoảng 512 px của board, nên khi zoom gấp 3 vẫn còn nét.</li><li><strong>Độ tương phản thấp:</strong> các mặt trong pattern chỉ đậm hoặc nhạt hơn nền một chút, để dây và cục lông trên board luôn nổi rõ.</li><li><strong>Xếp chéo:</strong> các mặt xếp theo hàng chéo, cách đều, khoảng 4 × 4 mặt trên một ô, khoảng trống giữa các mặt rộng hơn chính các mặt.</li><li>Phong cách <strong>phẳng, đơn giản</strong> (không 3D) để nền không tranh chú ý với các cục lông 3D.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Seamless repeating pattern tile, perfectly tileable on all four edges.</span></span>
<span class="line"><span>Simple flat cartoon icons of cute round fluffy ball faces with different expressions: sleeping with closed curved eyes, surprised with wide round eyes, squished with &quot;&gt; &lt;&quot; eyes, overjoyed with &quot;^ ^&quot; eyes and a big smile.</span></span>
<span class="line"><span>About 16 faces in the tile, arranged in evenly spaced diagonal rows running from the top left to the bottom right, every face the same size, generous empty space between them, each face slightly rotated for a playful feel.</span></span>
<span class="line"><span>Two-tone, very low contrast: the background is a solid warm cream colour #F2EEE6 and the faces are drawn in a slightly darker beige #E3DCCD with soft rounded shapes, no outlines darker than that.</span></span>
<span class="line"><span>Flat 2D, no shading, no gradients, no texture noise, no text.</span></span>
<span class="line"><span>Square, 2048 x 2048 pixels.</span></span>
<span class="line"><span>Negative: 3D, realistic, high contrast, black lines, bright colours, text, watermark, borders, frames, seams.</span></span></code></pre></div><p>Theme tối: dùng prompt trên, thay dòng <em>Two-tone</em> bằng:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Two-tone, very low contrast: the background is a solid deep navy blue #1F2335 and the faces are drawn in a slightly lighter navy #2A3049 with soft rounded shapes, no outlines lighter than that.</span></span></code></pre></div><h3 id="_9-awake-hand-png-bat-buoc-mat-thuc-va-ban-tay-tutorial-hai-anh-trong-mot-lan-gen" tabindex="-1">9. <code>awake-hand.png</code> (bắt buộc): mặt &quot;thức&quot; và bàn tay tutorial, <strong>hai ảnh trong một lần gen</strong> <a class="header-anchor" href="#_9-awake-hand-png-bat-buoc-mat-thuc-va-ban-tay-tutorial-hai-anh-trong-mot-lan-gen" aria-label="Permalink to &quot;9. \`awake-hand.png\` (bắt buộc): mặt &quot;thức&quot; và bàn tay tutorial, **hai ảnh trong một lần gen**&quot;">​</a></h3><p>Một ảnh ngang chia đôi: <strong>nửa trái là mặt thức</strong>, <strong>nửa phải là bàn tay tutorial</strong>. Lệnh <code>npm run art:fluffy</code> tự cắt hai nửa (mặt thành <code>face-awake.png</code> cùng tỉ lệ với các mặt khác, bàn tay thành <code>hand.png</code>). Muốn gen riêng từng ảnh thì đặt tên <code>face-awake.png</code> và <code>hand.png</code>, lệnh dùng hai file đó thay cho nửa tương ứng.</p><ul><li><strong>Mặt thức:</strong> cục lông đã bị va chạm thì không ngủ nữa mà <strong>thức, mở mắt</strong>, thay cho sọc trắng của bản thường. Mắt mở bình thường, bình tĩnh (nhỏ hơn mắt ngạc nhiên), miệng cười nhẹ. Cùng phong cách, cùng nét, cùng cỡ với các mặt trong <code>face.png</code> (dùng <code>face.png</code> làm ảnh tham chiếu).</li><li>Hai thứ này <strong>không có ảnh tạm</strong>: chưa có ảnh thì game giữ như cũ (cặp đã va chạm vẫn ngủ và có sọc trắng, tutorial vẫn dùng 👆). Có ảnh và chạy <code>npm run art:fluffy</code> là game tự đổi.</li><li><strong>Bàn tay tutorial:</strong> thay bàn tay emoji 👆 đang chỉ vào cục cần tap. Một <strong>bàn chân / bàn tay lông xù trắng</strong> kiểu cục lông, <strong>một ngón chỉ thẳng lên trên</strong>, đầu ngón ở trên cùng của hình (game tự tìm đầu ngón để đặt đúng vào cục). Có đệm thịt hồng là đẹp. Viền nâu đậm nhẹ để nổi trên cả nền sáng lẫn nền tối.</li><li>Hai hình <strong>không chạm vạch giữa</strong>, mỗi hình nằm gọn trong nửa của nó, khoảng trống rộng ở giữa.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Style: cute 3D cartoon render, soft and squishy, plush toy look, smooth soft lighting from the top left, gentle ambient occlusion, funny and adorable, clean simple shapes that read at a very small size, high resolution.</span></span>
<span class="line"><span>One wide image split into two separate items side by side, with a wide empty gap between them, nothing crossing the middle of the image.</span></span>
<span class="line"><span>LEFT HALF: only a cartoon face to be placed on top of a round fluffy ball, in exactly the same style as the reference faces: two calm open eyes (simple glossy dark brown-black round eyes with a small white highlight, smaller and calmer than a surprised face), a tiny gentle smile, two soft pink blush ovals on the cheeks. Expression: awake and calm, just woke up, content. No body, no fur, no head outline.</span></span>
<span class="line"><span>RIGHT HALF: a cute fluffy white plush paw-hand like the fur of a pom-pom creature, with one finger pointing straight up and the other fingers curled, soft pink paw pads, a thin warm dark brown outline so it reads on both light and dark backgrounds. The fingertip is the highest point of the drawing. Seen from the front, no arm or only a short wrist.</span></span>
<span class="line"><span>Isolated on a transparent background (if transparency is not available: a pure flat chroma-key green background #00FF00, with nothing green in the drawings).</span></span>
<span class="line"><span>Wide 2:1 image, 2048 x 1024 pixels.</span></span>
<span class="line"><span>Negative: body, ball, head outline, text, watermark, extra fingers, realistic human hand, nails, shadow on the ground, objects crossing the middle, more than two items.</span></span></code></pre></div><p>Mẹo: đưa <code>face.png</code> vào làm <strong>ảnh tham chiếu</strong> để mặt thức ra cùng nét với ba mặt kia.</p><h2 id="goi-y-them" tabindex="-1">Gợi ý thêm <a class="header-anchor" href="#goi-y-them" aria-label="Permalink to &quot;Gợi ý thêm&quot;">​</a></h2><ul><li><strong>Pattern dạng SVG</strong> (nếu bạn vẽ được, ví dụ trong Figma hoặc Illustrator): một ô SVG với các mặt vẽ bằng nét vector sẽ <strong>nét ở mọi mức zoom</strong> và nhẹ hơn PNG nhiều. Có SVG thì mình dùng SVG thay cho hai file <code>pattern-*.png</code>, đổi màu theo theme bằng code.</li><li>Nếu ảnh mặt ra không cùng vị trí giữa bốn file, gửi luôn cho mình: mình sẽ căn lại vị trí và cỡ cho khớp với thân khi xử lý.</li></ul><h2 id="gui-anh" tabindex="-1">Gửi ảnh <a class="header-anchor" href="#gui-anh" aria-label="Permalink to &quot;Gửi ảnh&quot;">​</a></h2><ol><li>Bỏ ảnh gốc vào <code>art/fluffy/</code> với đúng tên file như trên.</li><li>Chạy <code>npm run art:fluffy</code> (<code>tools/fluffy-art.ts</code>): tạo bản cỡ game trong <code>src/assets/fluffy/</code>. Game chỉ đọc thư mục này, nên chạy lại lệnh mỗi khi đổi ảnh gốc. Ảnh nào chưa có thì game dùng ảnh tạm vẽ bằng code (<code>src/scenes/fluffy.ts</code>).</li></ol><p>Lệnh làm gì với từng ảnh:</p><ul><li><strong><code>ball.png</code></strong>: cắt vuông quanh cục lông, thu về 512 × 512. Ánh sáng sẵn có trong ảnh bị làm phẳng hẳn (<code>MATTE</code> = 0), chi tiết sợi lông đậm gấp 2 (<code>DETAIL</code>). Ảnh ra <strong>không có ánh sáng</strong>: game tự đánh sáng cục lông như một quả cầu mềm (<code>ballTexture</code> trong <code>src/scenes/fluffy.ts</code>), theo các số <code>LIGHT_ANGLE</code>, <code>LIGHT_HEIGHT</code>, <code>LIGHT_AMBIENT</code>, <code>LIGHT_DIFFUSE</code>, <code>LIGHT_SHEEN</code> trong <code>src/game/tuning.ts</code>. Chỉnh các số này ngay khi chơi bằng nhóm <strong>Ball light</strong> trong cheat ⚙ dev, bấm Confirm khi chạy local để ghi vào code. Game coi thân tròn chiếm 90% khung (lông xù ra ngoài một chút).</li><li><strong>Mặt:</strong> <code>face.png</code> có thể chứa <strong>ba mặt trong một tấm</strong> (ngạc nhiên trên trái, <code>&gt; &lt;</code> trên phải, <code>^ ^</code> ở dưới): lệnh tự tách. <code>face-sleep.png</code> để riêng. Mỗi mặt được cắt quanh nét vẽ, đưa về <strong>cùng một tỉ lệ</strong> (mặt từ ảnh riêng được co cho bằng bề rộng các mặt trong tấm) và đặt giữa khung chung 640 × 360. Có <code>face-surprised.png</code> / <code>face-ouch.png</code> / <code>face-happy.png</code> riêng thì dùng chúng thay cho phần tương ứng trong <code>face.png</code>.</li><li>Vị trí mặt trên thân chỉnh trong code (<code>faceFrame</code> trong <code>src/scenes/fluffy.ts</code>): mặt rộng khoảng 68% đường kính thân, hạ xuống 10% bán kính.</li><li><strong><code>heart.png</code></strong>: cắt vuông, 160 × 160. Ảnh màu gì cũng được (đang là tim đỏ): game <strong>tô lại theo màu của cặp</strong> lúc hai cục ôm nhau (độ sáng giữ nguyên, chỗ bóng trắng vẫn trắng).</li><li><strong><code>fur.png</code></strong>: cắt vuông, 128 × 128, game tô theo màu cục lông. Nên là lông trắng hoặc xám.</li><li><strong><code>pattern-light.png</code> / <code>pattern-dark.png</code></strong>: làm <strong>thưa, nhỏ và mờ hơn</strong> rồi lưu JPEG. Lệnh tìm từng mặt trong ô (mảng khác màu nền), thu mặt còn một nửa, giãn khoảng cách ra 2 lần (ô mới 2 lần ô cũ, vẫn nối liền mép, vẫn xếp chéo) và nhạt đi 45% về phía màu nền. Chỉnh ba số <code>SPREAD</code>, <code>SHRINK</code>, <code>FADE</code> ở đầu phần pattern trong <code>tools/fluffy-art.ts</code>; đổi <code>SPREAD</code> thì đổi cả <code>patternWorld</code> trong <code>src/scenes/fluffy.ts</code>.</li></ul><p>Bộ ảnh hiện tại (đã dùng trong game):</p><table tabindex="0"><thead><tr><th>File</th><th>Ghi chú</th></tr></thead><tbody><tr><td><code>ball.png</code></td><td>1024 × 1024, lông trắng, trong suốt</td></tr><tr><td><code>face.png</code></td><td>ba mặt surprised / ouch / happy trong một tấm</td></tr><tr><td><code>face-sleep.png</code></td><td>mặt ngủ, vẽ to hơn các mặt trong <code>face.png</code> (lệnh tự co lại)</td></tr><tr><td><code>heart.png</code>, <code>fur.png</code></td><td>trong suốt</td></tr><tr><td><code>pattern-light.png</code>, <code>pattern-dark.png</code></td><td>1254 × 1254, nối liền mép</td></tr></tbody></table><p>Nếu sau này muốn nền nét hơn khi zoom tối đa: xin pattern 2048 × 2048 (ô gốc phủ 512 px của board, zoom 3 lần cần khoảng 1536 px trở lên).</p><p>Quy cách khi đặt ảnh mới:</p><table tabindex="0"><thead><tr><th>File</th><th>Mức</th><th>Cỡ</th></tr></thead><tbody><tr><td><code>ball.png</code></td><td>bắt buộc</td><td>512 × 512</td></tr><tr><td><code>face-sleep.png</code>, <code>face-surprised.png</code>, <code>face-ouch.png</code>, <code>face-happy.png</code></td><td>bắt buộc</td><td>512 × 512, cùng vị trí mặt</td></tr><tr><td><code>pattern-light.png</code>, <code>pattern-dark.png</code></td><td>bắt buộc</td><td>2048 × 2048, nối liền mép</td></tr><tr><td><code>fur.png</code></td><td>nên có</td><td>128 × 128</td></tr><tr><td><code>heart.png</code></td><td>nên có</td><td>128 × 128</td></tr><tr><td><code>awake-hand.png</code> (hoặc <code>face-awake.png</code> + <code>hand.png</code>)</td><td>bắt buộc</td><td>2048 × 1024, mặt thức bên trái, bàn tay bên phải</td></tr></tbody></table>`,45)])])}const u=t(c,[["render",h]]);export{p as __pageData,u as default};
